    {
      "id": "TC-002",
      "title": "Client calls an endpoint not assigned to its role",
      "covers": [
        "SW-002"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A client with a specific role is registered. The role is NOT assigned access to a specific endpoint (e.g., /api/v1/admin).",
      "test_inputs": "Client credentials for the role, target endpoint URL not assigned to the role.",
      "assumptions": "The gateway is running and the target endpoint exists in the system but is restricted.",
      "steps": [
